from starlette.responses import HTMLResponse


def _html_safe_json(value: Any) -> str:
    """Serialize a value to JSON that is safe to embed inside an HTML <script> tag."""
    return (
        json.dumps(value)
        .replace("<", "\\u003c")
        .replace(">", "\\u003e")
        .replace("&", "\\u0026")
    )
